```python
class Calendar:
    def __init__(self):
        self.calendar = {}

    def add_event(self, event_name, start_date, end_date):
        """Add an event to the calendar."""
        if start_date not in self.calendar:
            self.calendar[start_date] = []
        self.calendar[start_date].append((event_name, end_date))
        print(f"Event added successfully! ({event_name} from {start_date} to {end_date})")

    def remove_event(self, event_name, start_date):
        """Remove an event from the calendar."""
        if start_date in self.calendar and event_name in [event[0] for event in self.calendar[start_date]]:
            self.calendar[start_date].remove((event_name, None))
            print(f"Event removed successfully! ({event_name} from {start_date})")
        else:
            print("Event not found in the calendar.")

    def view_events(self, start_date):
        """View events in the calendar for a given date."""
        if start_date in self.calendar:
            print(f"Events on {start_date}:")
            for event_name, end_date in self.calendar[start_date]:
                print(f"- {event_name} ({end_date} if available)")
        else:
            print(f"No events on {start_date}.")


# Example usage
calendar = Calendar()

while True:
    command = input("Enter a command (add, remove, view, or quit): ").lower()

    if command == "add":
        event_name = input("Enter event name: ")
        start_date = input("Enter start date (format: YYYY-MM-DD): ")
        end_date = input("Enter end date (leave blank for no end date): ")
        calendar.add_event(event_name, start_date, end_date)

    elif command == "remove":
        event_name = input("Enter event name: ")
        start_date = input("Enter start date (format: YYYY-MM-DD): ")
        calendar.remove_event(event_name, start_date)

    elif command == "view":
        start_date = input("Enter start date (format: YYYY-MM-DD): ")
        calendar.view_events(start_date)

    elif command == "quit":
        break

    else:
        print("Invalid command. Please try again.")
